    def fact(i,url,note,**patch):
        result[i]=dict(outcome='approved',note=note,patch=patch,evidence=[dict(url=url,note=note,role='factual',status='pass',confidence='medium')])
    def wiki(i,note,**patch):
        ref=refs[i]
        if ref['status']!='fetched':raise ValueError('Missing inspected reference '+str(i))
